curl.exe -sS --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T "order[1-2].eml" smtp://127.0.0.1:8080/example.com
curl.exe -sS -o NUL --retry 10 --retry-all-errors --retry-delay 1 -u ann@example.com:annpass -X "FETCH 2 FLAGS" imap://127.0.0.1:8081/INBOX
curl.exe -sS -o "synced#1.eml" -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX;UID=[1-2]"
